const workloadHints={"id": {"hint": "Use a unique reference for one workload or end-to-end service. Keep the same ID when comparing candidates.", "example": "e.g. WL-001", "source": "Service catalog or architecture inventory"}, "name": {"hint": "Name the capability being assessed, rather than a server or vendor product. Set a boundary that can be assessed as one service.", "example": "e.g. Secure institutional file exchange", "source": "Service catalog and workload description"}, "owner": {"hint": "Who inside the institution is accountable for the service outcome and requirements? Identify a person or role, even when operation will be outsourced.", "example": "e.g. Head of Institutional Information Services", "source": "Service ownership record"}, "criticality": {"hint": "Rate the impact of losing or compromising this service. High: material mission, systemic or critical-service impact. Medium: significant but tolerable disruption. Low: limited impact with a workable alternative. Use your approved institutional tiers where available.", "example": "", "source": "Business impact analysis and service tier"}, "classification": {"hint": "Use the institution\u2019s data-classification labels. Include personal, confidential or restricted information and the most sensitive data the service will process.", "example": "e.g. Confidential; personal data; restricted attachments", "source": "Data owner and information-classification policy"}, "capability": {"hint": "Describe the outcome the workload must deliver: for whom, what it does, when it must be available, and what success means. Describe target needs for this design.", "example": "e.g. Exchange sensitive documents with approved external entities, with traceable receipt and controlled access.", "source": "Business sponsor and agreed service requirements"}, "rto": {"hint": "RTO = maximum acceptable time to restore the service after disruption. Enter the target in hours and explain the business deadline. Use decimal hours for shorter durations. This is a target, not an assumed provider promise.", "example": "e.g. 2 hours; restored before the next reporting window", "source": "Business impact analysis and continuity owner"}, "rpo": {"hint": "RPO = maximum acceptable loss of data, measured in time. Enter the target in minutes; this is a data-loss window, not restoration time. An RPO of 15 minutes means up to 15 minutes of recent changes may be lost. Zero requires an explicit no-data-loss requirement.", "example": "e.g. 15 minutes of submitted transactions", "source": "Data owner and recovery requirements"}, "jurisdiction": {"hint": "State approved or prohibited locations for data, backups, telemetry and support access. Include who controls encryption keys and administration. \u201cEU hosting\u201d alone does not settle jurisdiction or control sovereignty.", "example": "e.g. EU/EEA data and backups; institution-controlled keys; approved privileged support locations", "source": "Data governance, legal, security and provider requirements"}, "latency": {"hint": "Identify which interactions need low delay or local proximity. Give a measured target where known, the endpoints, throughput and data-transfer volumes. If no tight constraint exists, say so.", "example": "e.g. \u226420 ms round-trip to local identity service; 200 GB daily transfers", "source": "Network architecture and performance requirements"}, "dependencies": {"hint": "List each service the workload needs, its owner, and what happens if it fails. Cover identity, keys, DNS, network links, data sources, integrations and providers. Include recovery order and telemetry/incident interfaces.", "example": "e.g. Entra ID \u2192 authentication; PKI \u2192 certificates; external network link \u2192 delivery. Identity and certificates must recover before file exchange.", "source": "Dependency map, integration owners and recovery design"}, "needs": {"hint": "Describe baseline and peak demand, growth, storage, performance, operating hours and availability. Identify any HSM, GPU, dedicated hardware, container runtime, license or AI requirement. Separate confirmed needs from assumptions.", "example": "e.g. 500 users; 100 concurrent transfers; 5 TB initial storage; 20% annual growth; HSM-backed keys; peaks at month-end.", "source": "Business volumes, sizing assumptions and technical requirements"}};
